feat(workflow): trace durable agent runs as a single operation (#24408)

## Background

Global telemetry integrations were available inside model steps, but
invisible to the isolated workflow body. Each model call produced its
own root operation. A multi-step agent run therefore appeared as several
disconnected traces.

There was no span representing the entire run with its original prompt,
final output, and tool executions. Keeping a root span in memory
wouldn’t solve this because workflow steps can execute in different
processes

https://github.com/vercel/ai/issues/23618

## Summary

- The workflow records its lifecycle events and timestamps
- A preparation step captures trace context and sampling, then passes
that context into model steps.
- Model and provider HTTP spans are emitted live; the enclosing root,
step, and tool spans are reconstructed when the run ends or suspends.
- The bridge supplies matching IDs so everything joins one tree

## End-to-End Verification

verified by running the reproduction:

<details>

```ts
import { OpenTelemetry, OpenTelemetryIdGenerator } from '@ai-sdk/otel';
import { trace } from '@opentelemetry/api';
import {
  BasicTracerProvider,
  InMemorySpanExporter,
  SimpleSpanProcessor,
} from '@opentelemetry/sdk-trace-base';
import {
  buildWorkflowTests,
  getWorkflowRef,
  setupWorkflowTests,
  teardownWorkflowTests,
} from '@workflow/vitest';
import { registerTelemetry } from 'ai';
import { mkdir, mkdtemp, rm } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { start } from 'workflow/api';
import { run } from '../lib/run';

run(async () => {
  const exporter = new InMemorySpanExporter();
  const durable = new OpenTelemetryIdGenerator();
  const provider = new BasicTracerProvider({
    idGenerator: durable,
    sampler: durable,
    spanProcessors: [new SimpleSpanProcessor(exporter)],
  });
  trace.setGlobalTracerProvider(provider);
  registerTelemetry(new OpenTelemetry({ durable }));

  const cwd = dirname(
    fileURLToPath(import.meta.resolve('@ai-sdk/workflow/package.json')),
  );
  const artifactsDir = join(cwd, '.workflow-vitest');
  await mkdir(artifactsDir, { recursive: true });
  const rootDir = await mkdtemp(join(artifactsDir, 'issue-23618-'));
  const options = { cwd, rootDir };
  const originalCwd = process.cwd();

  try {
    // Keep the compiler's SWC cache in the workflow package's ignored directory.
    process.chdir(cwd);
    await buildWorkflowTests(options);
    await setupWorkflowTests(options);

    // Reuse the workspace fixture: a model calls addNumbers, then returns
    // "The sum is 5". Calling it through start() exercises workflow isolation.
    const workflowRun = await start(
      getWorkflowRef('agentToolLoopWithGlobalTelemetry'),
      [2, 3],
    );
    console.log('Result:', await workflowRun.returnValue);
    await provider.forceFlush();

    const spans = exporter
      .getFinishedSpans()
      .filter(span => span.instrumentationScope.name === 'gen_ai');

    function printTree(parentId: string | undefined, depth = 0) {
      for (const span of spans.filter(
        candidate => candidate.parentSpanContext?.spanId === parentId,
      )) {
        console.log(`${'  '.repeat(depth)}${span.name}`);
        printTree(span.spanContext().spanId, depth + 1);
      }
    }
    printTree(undefined);

    const root = spans.find(span => span.name.startsWith('invoke_agent '));
    console.log('Root prompt:', root?.attributes['gen_ai.input.messages']);
    console.log('Root output:', root?.attributes['gen_ai.output.messages']);
    console.log(
      'Trace count:',
      new Set(spans.map(span => span.spanContext().traceId)).size,
    );
  } finally {
    process.chdir(originalCwd);
    await teardownWorkflowTests();
    await provider.shutdown();
    trace.disable();
    await rm(rootDir, { recursive: true, force: true, maxRetries: 5 });
  }
});
```

</details>

